// Selected by the `nish-i32` condition even though the manifest declares it
// *after* plain `nish`: the mode-qualified condition is the plain one refined,
// so it wins whichever order the package wrote the two in. `helper` is private
// to the package and carries its prefix (WP21 S1).
const helper = (): i32 => 50;

export const seed = (): i32 => helper() + helper();
